import{_ as n,o as e,c as t,a2 as i}from"./chunks/framework.DBU8LMUS.js";const g=JSON.parse('{"title":"Moderasi Konten","description":"","frontmatter":{"title":"Moderasi Konten","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/admin/moderasi.md","filePath":"latest/admin/moderasi.md","lastUpdated":1786334463000}'),o={name:"latest/admin/moderasi.md"};function r(l,a,d,s,u,m){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="moderasi-konten" tabindex="-1">Moderasi Konten <a class="header-anchor" href="#moderasi-konten" aria-label="Permalink to &quot;Moderasi Konten&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Moderasi Konten</strong> adalah tempat admin meninjau <strong>laporan</strong> dari pengguna dan menindaklanjuti konten yang melanggar aturan komunitas. Admin juga dapat memoderasi konten secara langsung berdasarkan jenisnya.</p><h2 id="meninjau-laporan" tabindex="-1">Meninjau Laporan <a class="header-anchor" href="#meninjau-laporan" aria-label="Permalink to &quot;Meninjau Laporan&quot;">​</a></h2><ol><li>Masuk dengan akun yang memiliki kemampuan <code>moderate_reports</code>.</li><li>Buka menu <strong>Admin</strong>, lalu pilih <strong>Moderasi Konten</strong>.</li><li>Daftar laporan ditampilkan dengan informasi: <ul><li>Jenis konten yang dilaporkan (lowongan, pengumuman, polling, grup, galeri, atau profil).</li><li>Alasan pelaporan.</li><li>Status laporan.</li></ul></li></ol><h3 id="menindaklanjuti-laporan" tabindex="-1">Menindaklanjuti Laporan <a class="header-anchor" href="#menindaklanjuti-laporan" aria-label="Permalink to &quot;Menindaklanjuti Laporan&quot;">​</a></h3><ol><li>Buka detail laporan.</li><li>Tinjau konten yang dilaporkan.</li><li>Pilih tindakan: <ul><li><strong>Tindaklanjuti</strong>: konten dianggap melanggar; hapus konten atau ambil tindakan lain (misalnya menonaktifkan pengguna).</li><li><strong>Selesaikan</strong>: konten dinilai aman dan laporan ditutup.</li><li><strong>Tolak</strong>: laporan dianggap tidak valid.</li></ul></li><li>Klik <strong>Simpan</strong> untuk memperbarui status laporan.</li></ol><h2 id="memoderasi-konten-berdasarkan-jenis" tabindex="-1">Memoderasi Konten Berdasarkan Jenis <a class="header-anchor" href="#memoderasi-konten-berdasarkan-jenis" aria-label="Permalink to &quot;Memoderasi Konten Berdasarkan Jenis&quot;">​</a></h2><h3 id="lowongan-moderate-jobs" tabindex="-1">Lowongan (<code>moderate_jobs</code>) <a class="header-anchor" href="#lowongan-moderate-jobs" aria-label="Permalink to &quot;Lowongan (`moderate_jobs`)&quot;">​</a></h3><ul><li>Hapus lowongan yang tidak valid, palsu, atau melanggar aturan.</li><li>Tutup lowongan yang sudah tidak relevan.</li></ul><h3 id="pengumuman-moderate-announcements" tabindex="-1">Pengumuman (<code>moderate_announcements</code>) <a class="header-anchor" href="#pengumuman-moderate-announcements" aria-label="Permalink to &quot;Pengumuman (`moderate_announcements`)&quot;">​</a></h3><ul><li>Hapus pengumuman yang berisi informasi menyesatkan atau tidak pantas.</li></ul><h3 id="polling-moderate-polls" tabindex="-1">Polling (<code>moderate_polls</code>) <a class="header-anchor" href="#polling-moderate-polls" aria-label="Permalink to &quot;Polling (`moderate_polls`)&quot;">​</a></h3><ul><li>Hapus atau tutup polling yang provokatif atau melanggar aturan.</li></ul><h3 id="grup-moderate-groups" tabindex="-1">Grup (<code>moderate_groups</code>) <a class="header-anchor" href="#grup-moderate-groups" aria-label="Permalink to &quot;Grup (`moderate_groups`)&quot;">​</a></h3><ul><li>Hapus grup yang melanggar aturan.</li><li>Keluarkan anggota yang berperilaku tidak pantas.</li></ul><h3 id="galeri-moderate-gallery" tabindex="-1">Galeri (<code>moderate_gallery</code>) <a class="header-anchor" href="#galeri-moderate-gallery" aria-label="Permalink to &quot;Galeri (`moderate_gallery`)&quot;">​</a></h3><ul><li>Hapus foto yang tidak pantas atau melanggar privasi. Penghapusan juga menghilangkan berkas foto dari penyimpanan.</li></ul><h2 id="status-laporan" tabindex="-1">Status Laporan <a class="header-anchor" href="#status-laporan" aria-label="Permalink to &quot;Status Laporan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Baru</strong></td><td>Laporan masuk dan belum ditinjau.</td></tr><tr><td><strong>Ditindaklanjuti</strong></td><td>Konten dianggap melanggar dan telah diambil tindakan.</td></tr><tr><td><strong>Selesai</strong></td><td>Laporan ditinjau dan konten dinilai aman.</td></tr><tr><td><strong>Ditolak</strong></td><td>Laporan dianggap tidak valid.</td></tr></tbody></table><h2 id="prinsip-moderasi" tabindex="-1">Prinsip Moderasi <a class="header-anchor" href="#prinsip-moderasi" aria-label="Permalink to &quot;Prinsip Moderasi&quot;">​</a></h2><ul><li>Tinjau setiap laporan secara <strong>objektif</strong> dan berdasarkan aturan komunitas.</li><li>Gunakan <strong>prinsip hak akses minimum</strong> — setiap admin hanya memoderasi jenis konten sesuai kemampuannya.</li><li>Catat keputusan penting agar dapat diaudit melalui <strong>log aktivitas</strong>.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/admin/impor-ekspor">Impor &amp; Ekspor CSV</a> untuk pengelolaan data massal.</p>',23)])])}const k=n(o,[["render",r]]);export{g as __pageData,k as default};
